scwin.maxLenCheckVars = undefined; try { scwin.maxLenCheckVars = /* sdd-asis-lifecycle:begin maxLenCheckVars — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Array()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05001' }); }

scwin.maxLenCheckNames = undefined; try { scwin.maxLenCheckNames = /* sdd-asis-lifecycle:begin maxLenCheckNames — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Array()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05001' }); }

scwin.maxLenCheckMax = undefined; try { scwin.maxLenCheckMax = /* sdd-asis-lifecycle:begin maxLenCheckMax — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Array()/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05001' }); }

scwin.l = undefined; try { scwin.l = /* sdd-asis-lifecycle:begin l — as-is 원문 본문(전환 이관 · 포팅 적용됨) */screen.width/2 - scwin.w/2/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05001' }); }

scwin.t = undefined; try { scwin.t = /* sdd-asis-lifecycle:begin t — as-is 원문 본문(전환 이관 · 포팅 적용됨) */screen.height/2 - scwin.h/2/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05001' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_sessionFill();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil05001.onpageload' });
    }
};


