/**
 * @method
 * @name scwin.onload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onload = function () {
    /* sdd-asis-lifecycle:begin fn_Onload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form = (document.prelistMainForm || { elements: [] });
    $c.util.getComponent('rd_prelmInvstgComTpCd1').setItemDisabled(2, !!(true));
    if ($c.util.getComponent("dma_RegisterReq").get("billLstSaveStatCd") === "") {
        $c.util.getComponent("dma_RegisterReq").set("billLstSaveStatCd", "0");
    }
    if ($c.util.getComponent("dma_RegisterReq").get("billLstSaveStatCd") === "") {
        return;
    }
    scwin.onloadDataSet();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.onloadDataSet
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onloadDataSet = function () {
    /* sdd-asis-lifecycle:begin fn_OnloadDataSet — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const corpRegNo = $c.util.getComponent("dma_RegisterReq").get("corpRegNo");
    const bzRegNo = $c.util.getComponent("dma_RegisterReq").get("bzRegNo");
    const fscRegDd = $c.util.getComponent('cal_fscRegDd').getValue();
    const billSubmitDd = $c.util.getComponent('cal_billSubmitDd').getValue();
    const clmPlandocSubmitDd = $c.util.getComponent('cal_clmPlandocSubmitDd').getValue();
    const zipcd = $c.util.getComponent("dma_RegisterReq").get("zipcd");
    const foundDd = $c.util.getComponent('cal_foundDd').getValue();
    if (corpRegNo.length != 0) {
        $c.util.getComponent('ipt_corpRegNo1').setValue(corpRegNo.substring(0, 6));
        $c.util.getComponent('ipt_corpRegNo2').setValue(corpRegNo.substring(6));
    }
    if (bzRegNo.length != 0) {
        $c.util.getComponent('ipt_bzRegNo1').setValue(bzRegNo.substring(0, 3));
        $c.util.getComponent('ipt_bzRegNo2').setValue(bzRegNo.substring(3, 5));
        $c.util.getComponent('ipt_bzRegNo3').setValue(bzRegNo.substring(5));
    }
    if (zipcd.length != 0) {
        $c.util.getComponent('ipt_zipcd1').setValue(zipcd.substring(0, 3));
        $c.util.getComponent('ipt_zipcd2').setValue(zipcd.substring(3));
    }
    scwin.checkFscRegYn($c.util.getComponent('ipt_fscRegYn').getValue());
    if ($c.util.getComponent("dma_RegisterReq").get("prelmInvstgComTpCd") === "1") {
        $c.util.getComponent('slc_ventDesignRsnCd').setDisabled(false);
    } else {
        $c.util.getComponent('slc_ventDesignRsnCd').setDisabled(true);
    }
    /* sdd-asis-lifecycle:end */
};



