 * @returns
 * @hidden N
*/
scwin.setCorpInfo = async function (isurCd, corpRegNo, bzRegNo, repIsuCd, repIsuSrtCd, comNm, comEngNm, ceoNm, zipCd, addr, hPage, cntrIsoCd, foundDd, corpTelNo) {
    /* sdd-asis-lifecycle:begin setCorpInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_RegisterReq').reset();
    let isFCorp = false;
    const isurCd_first = isurCd.charAt(0);
    if (isNaN(isurCd_first)) {
        isFCorp = true;
    }
    if (('' !== isurCd) && (isurCd.length == 5)) {
        $c.util.getComponent("ipt_isurCd").setValue(isurCd);
    } else {
        await $c.win.alert('선택하신 법인의 고유코드가 존재하지 않거나 올바르지 않습니다.\n' + '헬프데스크로 문의바랍니다.');
        return;
    }
    if (('' !== corpRegNo) && (corpRegNo.length == 13)) {
        $c.util.getComponent("ipt_corpRegNo1").setValue(corpRegNo.substring(0, 6));
        $c.util.getComponent("ipt_corpRegNo2").setValue(corpRegNo.substring(6));
    } else {
        if (isFCorp) {
            await $c.win.alert('선택하신 외국법인의 법인등록번호가 존재하지 않거나 올바르지 않습니다.\n' + '직접 입력해주시기 바랍니다.');
            $c.util.getComponent('ipt_corpRegNo1').readOnly = false;
            $c.util.getComponent('ipt_corpRegNo2').readOnly = false;
        } else {
            await $c.win.alert('선택하신 법인의 법인등록번호가 존재하지 않거나 올바르지 않습니다.\n' + '헬프데스크로 문의바랍니다.');
            return;
        }
    }
    if (('' !== bzRegNo) && (bzRegNo.length == 10)) {
        $c.util.getComponent("ipt_bzRegNo1").setValue(bzRegNo.substring(0, 3));
        $c.util.getComponent("ipt_bzRegNo2").setValue(bzRegNo.substring(3, 5));
        $c.util.getComponent("ipt_bzRegNo3").setValue(bzRegNo.substring(5));
    } else {
        if (isFCorp) {
            await $c.win.alert('선택하신 외국법인의 사업자등록번호가 존재하지 않거나 올바르지 않습니다.\n' + '직접 입력해주시기 바랍니다.');
            $c.util.getComponent('ipt_bzRegNo1').readOnly = false;
            $c.util.getComponent('ipt_bzRegNo2').readOnly = false;
            $c.util.getComponent('ipt_bzRegNo3').readOnly = false;
        } else {
            await $c.win.alert('선택하신 법인의 사업자등록번호가 존재하지 않거나 올바르지 않습니다.\n' + '헬프데스크로 문의바랍니다.');
            return;
        }
    }
    if ('' !== comNm) {
        $c.util.getComponent("ipt_comNm").setValue(comNm);
    } else {
        await $c.win.alert('선택하신 법인의 회사명이 존재하지 않거나 올바르지 않습니다.\n' + '헬프데스크로 문의바랍니다.');
    }
    $c.util.getComponent("ipt_comEngNm").setValue(comEngNm);
    if ('' !== ceoNm) {
        $c.util.getComponent("ipt_repNm").setValue(ceoNm);
    } else {
        await $c.win.alert('선택하신 법인의 대표자명이 존재하지 않거나 올바르지 않습니다.\n' + '헬프데스크로 문의바랍니다.');
    }
    if (('' !== zipCd) && (zipCd.length == 6)) {
        $c.util.getComponent("ipt_zipcd1").setValue(zipCd.substring(0, 3));
        $c.util.getComponent("ipt_zipcd2").setValue(zipCd.substring(3));
    } else {
        if (isFCorp) {
            await $c.win.alert('선택하신 외국법인의 우편번호가 존재하지 않거나 올바르지 않습니다.\n' + '직접 입력해주시기 바랍니다.');
            $c.util.getComponent('ipt_zipcd1').readOnly = false;
            $c.util.getComponent('ipt_zipcd2').readOnly = false;
        } else {
            await $c.win.alert('선택하신 법인의 우편번호가 존재하지 않거나 올바르지 않습니다.\n' + '헬프데스크로 문의바랍니다.');
            return;
        }
    }
    $c.util.getComponent("ipt_addr").setValue(addr);
    $c.util.getComponent("slc_cntrIsoCd").setValue(cntrIsoCd);
    $c.util.getComponent("cal_foundDd").setValue(foundDd);
    $c.util.getComponent("ipt_telNo").setValue(corpTelNo);
    /* sdd-asis-lifecycle:end */
};


